// Generated from the editable example files. Run npm run examples:sync after changing them.
export const settingsHtml = "<good-main-view>\n  <good-heading-1>{{ detail() ? (workspace()?.name ?? 'Workspace not found') : 'Settings' }}</good-heading-1>\n  <good-summary>{{ detail() ? 'Manage workspace details, team access, and availability.' : 'Choose a workspace to review and manage its settings.' }}</good-summary>\n  <good-action-group good-main-view-actions spacing=\"small\">\n    @if (workspace()) {\n      @if (editing()) {\n        <good-button variant=\"outline\" (click)=\"cancel()\">Cancel</good-button>\n        <good-button (click)=\"save()\">Save changes</good-button>\n      } @else { <good-button (click)=\"edit()\">Edit settings</good-button> }\n    }\n    <good-button variant=\"ghost\" (click)=\"sourceOpen.set(true)\">View source</good-button>\n  </good-action-group>\n  <good-section><good-breadcrumbs [items]=\"breadcrumbs()\" /></good-section>\n  @if (!detail()) {\n    <good-section layout=\"settings\">\n      <good-heading-group><good-heading-2>Workspaces</good-heading-2><good-summary>Open a workspace to read its configuration before making changes.</good-summary></good-heading-group>\n      <good-input good-section-actions label=\"Search workspaces\" type=\"search\" size=\"small\" placeholder=\"Search workspaces\" [value]=\"query()\" (valueChange)=\"query.set($event)\" />\n      <good-table label=\"Workspaces\" frameAppearance=\"none\" density=\"compact\" [reorderable]=\"false\"\n        [data]=\"store.workspaces()\" [columns]=\"columns\" [getRowId]=\"rowId\" [searchTerm]=\"query()\">\n        <ng-template goodTableCell=\"name\" let-row><good-link [route]=\"'/examples/settings/' + row.id\">{{ row.name }}</good-link></ng-template>\n      </good-table>\n      <good-paragraph>Changes in this example are kept in memory for this session. Reloading restores the sample workspaces.</good-paragraph>\n    </good-section>\n  } @else if (workspace(); as current) {\n    @if (feedback()) { <good-section><good-paragraph role=\"status\">{{ feedback() }}</good-paragraph></good-section> }\n    <good-section layout=\"settings\">\n      <good-heading-group><good-heading-2>General</good-heading-2><good-summary>The name and region used to identify this workspace.</good-summary></good-heading-group>\n      @if (editing()) {\n        <form goodForm [fullWidth]=\"true\" [formGroup]=\"form\" (ngSubmit)=\"save()\">\n          <good-form-row>\n            <good-form-field><good-field-label forId=\"workspace-name\" [required]=\"true\">Workspace name</good-field-label>\n              <good-input inputId=\"workspace-name\" label=\"Workspace name\" formControlName=\"name\" [error]=\"form.controls.name.touched && form.controls.name.invalid\" />\n              @if (form.controls.name.touched && form.controls.name.invalid) { <good-error-text>Enter a workspace name.</good-error-text> }\n            </good-form-field>\n            <good-form-field><good-field-label forId=\"workspace-region\" [required]=\"true\">Region</good-field-label>\n              <good-input inputId=\"workspace-region\" label=\"Region\" formControlName=\"region\" [error]=\"form.controls.region.touched && form.controls.region.invalid\" />\n              @if (form.controls.region.touched && form.controls.region.invalid) { <good-error-text>Enter a region.</good-error-text> }\n            </good-form-field>\n          </good-form-row>\n        </form>\n      } @else {\n        <good-detail-list><div goodDetailRow><dt>Workspace name</dt><dd>{{ current.name }}</dd></div><div goodDetailRow><dt>Region</dt><dd>{{ current.region }}</dd></div></good-detail-list>\n      }\n    </good-section>\n    <good-section layout=\"settings\">\n      <good-heading-group><good-heading-2>Team access</good-heading-2><good-summary>Review the teams that can use this workspace.</good-summary></good-heading-group>\n      <good-action-group good-section-actions spacing=\"small\">\n        <good-input label=\"Search teams\" type=\"search\" size=\"small\" placeholder=\"Search teams\" [value]=\"memberQuery()\" (valueChange)=\"memberQuery.set($event)\" />\n        @if (editing()) { <good-button size=\"small\" variant=\"outline\" (click)=\"addMember()\">Add example team</good-button> }\n      </good-action-group>\n      <good-table label=\"Team access\" frameAppearance=\"none\" density=\"compact\" [reorderable]=\"false\"\n        [data]=\"displayedMembers()\" [columns]=\"memberColumns\" [getRowId]=\"rowId\" [searchTerm]=\"memberQuery()\" emptyMessage=\"No teams found\">\n        <ng-template goodTableCell=\"actions\" let-row>\n          @if (editing()) { <good-button size=\"small\" variant=\"ghost\" [ariaLabel]=\"'Remove ' + row.name\" (click)=\"removeMember(row.id)\">Remove</good-button> }\n          @else { <good-paragraph>—</good-paragraph> }\n        </ng-template>\n      </good-table>\n    </good-section>\n    <good-section layout=\"settings\">\n      <good-heading-group><good-heading-2>Availability</good-heading-2><good-summary>Set the recurring windows for this workspace. Each end time must follow its start time.</good-summary></good-heading-group>\n      @if (editing()) { <good-button good-section-actions size=\"small\" variant=\"outline\" (click)=\"addRow()\">Add window</good-button> }\n      @if (editing()) {\n        <form goodForm [fullWidth]=\"true\" [formGroup]=\"form\" (ngSubmit)=\"save()\">\n          @for (row of form.controls.schedule.controls; track row; let index = $index) {\n            <good-group appearance=\"plain\" [formGroup]=\"row\">\n              <good-form-row [columns]=\"3\">\n                <good-form-field><good-field-label [forId]=\"'day-' + row.controls.id.value\">Day</good-field-label>\n                  <good-input [inputId]=\"'day-' + row.controls.id.value\" [label]=\"'Day ' + (index + 1)\" formControlName=\"day\" [error]=\"row.controls.day.touched && row.controls.day.invalid\" />\n                  @if (row.controls.day.touched && row.controls.day.invalid) { <good-error-text>Enter a day.</good-error-text> }\n                </good-form-field>\n                <good-form-field><good-field-label [forId]=\"'start-' + row.controls.id.value\">From</good-field-label>\n                  <good-input [inputId]=\"'start-' + row.controls.id.value\" [label]=\"'From ' + (index + 1)\" placeholder=\"HH:MM\" formControlName=\"start\" [error]=\"row.touched && row.invalid\" />\n                </good-form-field>\n                <good-form-field><good-field-label [forId]=\"'end-' + row.controls.id.value\">Until</good-field-label>\n                  <good-input [inputId]=\"'end-' + row.controls.id.value\" [label]=\"'Until ' + (index + 1)\" placeholder=\"HH:MM\" formControlName=\"end\" [error]=\"row.touched && row.invalid\" />\n                </good-form-field>\n                <good-button good-form-row-actions variant=\"ghost\" [ariaLabel]=\"'Remove window ' + (index + 1)\" (click)=\"removeRow(index)\">Remove</good-button>\n              </good-form-row>\n              @if (row.touched && row.invalid) { <good-error-text>Enter a day and a valid start and end time. The end must be after the start.</good-error-text> }\n            </good-group>\n          } @empty { <good-paragraph>No availability windows. Add a window to get started.</good-paragraph> }\n        </form>\n      } @else {\n        <good-detail-list>\n          @for (row of current.schedule; track row.id) { <div goodDetailRow><dt>{{ row.day }}</dt><dd>{{ row.start }}–{{ row.end }}</dd></div> }\n        </good-detail-list>\n        @if (!current.schedule.length) { <good-paragraph>No availability windows configured.</good-paragraph> }\n      }\n    </good-section>\n    @if (!editing()) {\n      <good-section layout=\"settings\" appearance=\"danger\">\n        <good-heading-group><good-heading-2>Archive workspace</good-heading-2><good-summary>Remove this workspace from the active overview. Confirm its name before continuing.</good-summary></good-heading-group>\n        <good-button good-section-actions variant=\"outline\" (click)=\"archiveName.set(''); archiveOpen.set(true)\">Archive workspace</good-button>\n      </good-section>\n    }\n  } @else {\n    <good-section><good-alert tone=\"neutral\" title=\"Workspace not found\" message=\"This workspace is unavailable or has been archived.\" /><good-link route=\"/examples/settings\">Back to settings</good-link></good-section>\n  }\n</good-main-view>\n<good-modal [(open)]=\"archiveOpen\">\n  <good-modal-header title=\"Archive workspace\" />\n  <good-group appearance=\"plain\">\n    <good-paragraph>Enter {{ workspace()?.name }} to archive this workspace in the demo.</good-paragraph>\n    <good-input label=\"Workspace name to confirm\" [value]=\"archiveName()\" (valueChange)=\"archiveName.set($event)\" />\n    <good-action-group><good-button variant=\"outline\" (click)=\"archiveOpen.set(false)\">Cancel</good-button><good-button variant=\"destructive\" [disabled]=\"archiveName() !== workspace()?.name\" (click)=\"archive()\">Confirm archive</good-button></good-action-group>\n  </good-group>\n</good-modal>\n<good-modal [(open)]=\"sourceOpen\" size=\"large\" [scrollBody]=\"true\">\n  <good-modal-header title=\"Settings example source\" />\n  <good-code-block [code]=\"htmlSource\" language=\"html\" title=\"settings-page.html\" />\n  <good-code-block [code]=\"typescriptSource\" language=\"typescript\" title=\"settings-page.ts\" />\n</good-modal>\n";
export const settingsTs = "import { ChangeDetectionStrategy, Component, Injectable, computed, effect, inject, signal } from '@angular/core';\nimport { toSignal } from '@angular/core/rxjs-interop';\nimport { AbstractControl, FormArray, FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';\nimport { ActivatedRoute, Router } from '@angular/router';\nimport {\n  GoodActionGroupComponent, GoodAlertComponent, GoodBreadcrumbsComponent, GoodButtonComponent,\n  GoodCodeBlockComponent, GoodDetailListComponent, GoodDetailRowDirective, GoodErrorTextComponent,\n  GoodFieldLabelComponent, GoodFormDirective, GoodFormFieldComponent, GoodFormRowComponent,\n  GoodGroupComponent, GoodHeading1Component, GoodHeading2Component, GoodHeadingGroupComponent,\n  GoodInputComponent, GoodLinkComponent, GoodMainViewComponent, GoodModalComponent,\n  GoodModalHeaderComponent, GoodParagraphComponent, GoodSectionComponent, GoodSummaryComponent,\n  GoodTableCellDirective, GoodTableColumn, GoodTableComponent,\n} from '@cloudfrogger/goodui';\nimport { settingsHtml, settingsTs } from './source-code.generated';\n\ninterface ScheduleRow { id: string; day: string; start: string; end: string }\ninterface Member { id: string; name: string; role: string }\ninterface Workspace { id: string; name: string; region: string; members: Member[]; schedule: ScheduleRow[] }\n\n@Injectable({ providedIn: 'root' })\nexport class SettingsDemoStore {\n  readonly workspaces = signal<Workspace[]>([\n    { id: 'studio', name: 'Design studio', region: 'Europe', members: [\n      { id: 'team-1', name: 'Design team', role: 'Editor' }, { id: 'team-2', name: 'Review team', role: 'Viewer' },\n    ], schedule: [{ id: 'slot-1', day: 'Monday', start: '09:00', end: '17:00' }] },\n    { id: 'sandbox', name: 'Sandbox', region: 'North America', members: [], schedule: [] },\n    { id: 'research', name: 'Research lab', region: 'Europe', members: [], schedule: [] },\n  ]);\n}\n\nfunction scheduleGroup(row: ScheduleRow) {\n  return new FormGroup({\n    id: new FormControl(row.id, { nonNullable: true }),\n    day: new FormControl(row.day, { nonNullable: true, validators: [Validators.required] }),\n    start: new FormControl(row.start, { nonNullable: true, validators: [Validators.required, Validators.pattern(/^(?:[01]\\d|2[0-3]):[0-5]\\d$/)] }),\n    end: new FormControl(row.end, { nonNullable: true, validators: [Validators.required, Validators.pattern(/^(?:[01]\\d|2[0-3]):[0-5]\\d$/)] }),\n  }, { validators: (control: AbstractControl) => {\n    const { start, end } = control.value;\n    return start && end && start >= end ? { timeOrder: true } : null;\n  } });\n}\n\n@Component({\n  selector: 'example-settings-page', standalone: true,\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  imports: [ReactiveFormsModule, GoodMainViewComponent, GoodHeading1Component, GoodSummaryComponent,\n    GoodSectionComponent, GoodHeadingGroupComponent, GoodHeading2Component, GoodActionGroupComponent,\n    GoodButtonComponent, GoodInputComponent, GoodLinkComponent, GoodTableComponent, GoodTableCellDirective,\n    GoodBreadcrumbsComponent, GoodDetailListComponent, GoodDetailRowDirective, GoodFormDirective,\n    GoodFormFieldComponent, GoodFieldLabelComponent, GoodFormRowComponent, GoodGroupComponent,\n    GoodErrorTextComponent, GoodParagraphComponent, GoodAlertComponent, GoodModalComponent,\n    GoodModalHeaderComponent, GoodCodeBlockComponent],\n  templateUrl: './settings-page.html',\n})\nexport class SettingsPageComponent {\n  readonly store = inject(SettingsDemoStore);\n  private readonly router = inject(Router);\n  private readonly params = toSignal(inject(ActivatedRoute).paramMap);\n  readonly workspace = computed(() => this.store.workspaces().find(item => item.id === this.params()?.get('id')));\n  readonly detail = computed(() => !!this.params()?.get('id'));\n  readonly editing = signal(false);\n  readonly query = signal('');\n  readonly memberQuery = signal('');\n  readonly feedback = signal('');\n  readonly sourceOpen = signal(false);\n  readonly archiveOpen = signal(false);\n  readonly archiveName = signal('');\n  readonly htmlSource = settingsHtml;\n  readonly typescriptSource = settingsTs;\n  readonly draftMembers = signal<Member[]>([]);\n  readonly displayedMembers = computed(() => this.editing() ? this.draftMembers() : this.workspace()?.members ?? []);\n  readonly breadcrumbs = computed(() => [\n    { label: 'Settings', route: '/examples/settings' },\n    ...(this.detail() ? [{ label: this.workspace()?.name ?? 'Workspace not found' }] : []),\n  ]);\n  readonly form = new FormGroup({\n    name: new FormControl('', { nonNullable: true, validators: [Validators.required, Validators.pattern(/\\S/)] }),\n    region: new FormControl('', { nonNullable: true, validators: [Validators.required, Validators.pattern(/\\S/)] }),\n    schedule: new FormArray<ReturnType<typeof scheduleGroup>>([]),\n  });\n  readonly rowId = (row: { id: string }) => row.id;\n  readonly columns: GoodTableColumn<Workspace>[] = [\n    { accessorKey: 'name', header: 'Workspace', enableSorting: true },\n    { accessorKey: 'region', header: 'Region', meta: { visibleFrom: 'sm' } },\n    { id: 'members', header: 'Members', accessorFn: row => row.members.length, meta: { align: 'end' } },\n  ];\n  readonly memberColumns: GoodTableColumn<Member>[] = [\n    { accessorKey: 'name', header: 'Team', enableSorting: true },\n    { accessorKey: 'role', header: 'Access', meta: { visibleFrom: 'sm' } },\n    { id: 'actions', header: 'Actions', meta: { align: 'end' }, enableGlobalFilter: false },\n  ];\n  private nextId = 0;\n\n  constructor() {\n    effect(() => { this.params(); this.editing.set(false); this.feedback.set(''); this.archiveOpen.set(false); });\n  }\n  open(id: string): void { void this.router.navigate(['/examples/settings', id]); }\n  edit(): void {\n    const workspace = this.workspace();\n    if (!workspace) return;\n    this.form.reset({ name: workspace.name, region: workspace.region });\n    this.form.controls.schedule.clear();\n    workspace.schedule.forEach(row => this.form.controls.schedule.push(scheduleGroup(row)));\n    this.draftMembers.set(workspace.members.map(member => ({ ...member })));\n    this.feedback.set(''); this.editing.set(true);\n  }\n  cancel(): void { this.editing.set(false); this.feedback.set('Changes discarded.'); }\n  addRow(): void {\n    this.form.controls.schedule.push(scheduleGroup({ id: `new-slot-${++this.nextId}`, day: '', start: '09:00', end: '17:00' }));\n  }\n  removeRow(index: number): void { this.form.controls.schedule.removeAt(index); }\n  addMember(): void {\n    this.draftMembers.update(members => [...members, { id: `new-team-${++this.nextId}`, name: 'Example team', role: 'Viewer' }]);\n  }\n  removeMember(id: string): void { this.draftMembers.update(members => members.filter(member => member.id !== id)); }\n  save(): void {\n    this.form.markAllAsTouched();\n    if (this.form.invalid) { this.feedback.set('Check the highlighted fields before saving.'); return; }\n    const workspace = this.workspace();\n    if (!workspace) return;\n    const values = this.form.getRawValue();\n    this.store.workspaces.update(items => items.map(item => item.id === workspace.id\n      ? { ...item, ...values, name: values.name.trim(), region: values.region.trim(), members: this.draftMembers() } : item));\n    this.editing.set(false); this.feedback.set('Workspace settings saved for this demo session.');\n  }\n  archive(): void {\n    const workspace = this.workspace();\n    if (!workspace || this.archiveName() !== workspace.name) return;\n    this.store.workspaces.update(items => items.filter(item => item.id !== workspace.id));\n    this.archiveOpen.set(false);\n    void this.router.navigate(['/examples/settings']);\n  }\n}\n";
